-- JPAC Academy Guitar full 50-module draft rollout
-- Inserts Guitar draft curriculum only. No publication, media/tool activation, or student-state writes.
begin;
do $$
declare v_course uuid; v_level uuid; v_module uuid; v_lesson jsonb; v_rubric jsonb;
 v_level_title text; v_level_target int; v_review_notes text; r record; i int;
begin
 if (select count(*) from public.courses where slug='guitar')<>1 then raise exception 'Expected exactly one canonical guitar course'; end if;
 select id into v_course from public.courses where slug='guitar' for share;
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('jpac_sync_enrollment_progress','jpac_enforce_canonical_enrollment_progress') and (select count(*) from regexp_matches(regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g'),'m\.status=''published''','g'))=2 and strpos(regexp_replace(lower(pg_get_functiondef(p.oid)),'\s+','','g'),'m.status<>''archived''')=0)<>2
 or not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='enrollments' and t.tgname='enrollments_enforce_canonical_progress' and not t.tgisinternal and t.tgenabled<>'D')
 then raise exception 'Published-only Safe Draft Isolation is not active'; end if;
 if exists(select 1 from public.enrollments where course_id=v_course)
 or exists(select 1 from public.submissions s join public.activities a on a.id=s.activity_id where a.course_id=v_course)
 or exists(select 1 from public.lesson_progress p join public.lessons l on l.id=p.lesson_id join public.course_modules m on m.id=l.module_id where m.course_id=v_course)
 or exists(select 1 from public.activity_progress p join public.activities a on a.id=p.activity_id where a.course_id=v_course)
 or exists(select 1 from public.practice_logs p join public.activities a on a.id=p.activity_id where a.course_id=v_course)
 or exists(select 1 from public.xp_ledger where course_id=v_course)
 or exists(select 1 from public.certificates where course_id=v_course)
 or exists(select 1 from public.portfolio_projects p join public.activities a on a.id=p.activity_id where a.course_id=v_course)
 then raise exception 'Existing Guitar student/evidence dependency blocks rollout'; end if;
 for r in select * from jsonb_to_recordset('[{"level":1,"num":1,"title":"Guitar Basics: Holding Your Guitar","lessons":["Guitar and Bench Setup","Balanced Playing Posture","First Clean Chord or Note"],"practice":"Comfortable Guitar Setup Check","practiceInstructions":"Set the instrument securely, check shoulder/wrist relaxation, and rehearse one simple sound while maintaining posture.","challenge":"Safe Guitar Setup Performance","evidence":"Submit a short video showing safe posture, guitar position, relaxed fretting and strumming hands, and one clear chord or scale fragment.","rubric":[{"name":"Safe instrument handling","weight":25},{"name":"Posture and alignment","weight":25},{"name":"Hand position","weight":20},{"name":"Clear controlled sound","weight":20},{"name":"Reflection and submission completeness","weight":10}],"sort":1,"objective":"Develop and demonstrate source-aligned Guitar skills for Guitar Basics: Holding Your Guitar.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":2,"title":"First Chords: A, D, and E","lessons":["Building the A Chord","Building D and E Chords","Three-Chord Transition Practice"],"practice":"A-D-E Clarity Drill","practiceInstructions":"Hold each chord, check every string, and make slow transitions without rushing.","challenge":"First Three-Chord Progression","evidence":"Submit a continuous A-D-E performance with recognizable chord shapes, clear sound, and steady transitions.","rubric":[{"name":"Chord shape accuracy","weight":25},{"name":"String clarity","weight":20},{"name":"Transition control","weight":20},{"name":"Rhythm continuity","weight":20},{"name":"Preparation and reflection","weight":15}],"sort":2,"objective":"Develop and demonstrate source-aligned Guitar skills for First Chords: A, D, and E.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":3,"title":"Strumming Patterns Basics","lessons":["Downstroke Pulse","Upstroke Recovery","Combining Down-Up Patterns"],"practice":"Steady Strumming Ladder","practiceInstructions":"Perform downstrokes, upstrokes, and down-up combinations at a comfortable tempo.","challenge":"Three-Pattern Strumming Demonstration","evidence":"Submit three clearly counted strumming patterns with consistent pulse and relaxed motion.","rubric":[{"name":"Pattern accuracy","weight":25},{"name":"Steady pulse","weight":25},{"name":"Relaxed strumming technique","weight":20},{"name":"Dynamic control","weight":15},{"name":"Reflection and completeness","weight":15}],"sort":3,"objective":"Develop and demonstrate source-aligned Guitar skills for Strumming Patterns Basics.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":4,"title":"12-Bar Blues Introduction","lessons":["The 12-Bar Form","I-IV-V Chord Movement","First Blues Groove"],"practice":"Blues Form Walkthrough","practiceInstructions":"Count and play one slow 12-bar cycle with a simplified rhythm.","challenge":"Beginner 12-Bar Blues Performance","evidence":"Submit a complete 12-bar blues cycle and a brief explanation of the form.","rubric":[{"name":"Form accuracy","weight":25},{"name":"Chord movement","weight":20},{"name":"Groove and timing","weight":25},{"name":"Musical expression","weight":15},{"name":"Reflection and completeness","weight":15}],"sort":4,"objective":"Develop and demonstrate source-aligned Guitar skills for 12-Bar Blues Introduction.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":5,"title":"Chord Heroes: E, G, and C","lessons":["Building Em and G","Building C Major","G-C Transition Control"],"practice":"Chord Hero Sound Check","practiceInstructions":"Play Em, G, and C separately, then alternate G and C slowly.","challenge":"Three-Chord Clarity Challenge","evidence":"Submit Em, G, and C with clear strings and controlled G-C transitions.","rubric":[{"name":"Finger placement","weight":25},{"name":"Chord clarity","weight":25},{"name":"Transition accuracy","weight":20},{"name":"Rhythm control","weight":15},{"name":"Preparation and reflection","weight":15}],"sort":5,"objective":"Develop and demonstrate source-aligned Guitar skills for Chord Heroes: E, G, and C.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":6,"title":"R&B Groove: Two-Chord Jam","lessons":["Am and Dm Shapes","Down, Down-Up Groove","Playing with a Backing Pulse"],"practice":"Am-Dm Groove Loop","practiceInstructions":"Alternate Am and Dm while keeping the approved strumming pattern relaxed and steady.","challenge":"Two-Chord R&B Jam","evidence":"Submit a one-minute Am-Dm performance with a consistent R&B groove.","rubric":[{"name":"Chord accuracy","weight":20},{"name":"Transition control","weight":20},{"name":"Groove consistency","weight":25},{"name":"Feel and dynamics","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":6,"objective":"Develop and demonstrate source-aligned Guitar skills for R&B Groove: Two-Chord Jam.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":7,"title":"Pop Song Power: Your First Verse","lessons":["G-C-Em-D Progression","Standard Pop Strumming","Memorizing a Verse Form"],"practice":"Pop Verse Transition Loop","practiceInstructions":"Cycle G-C-Em-D slowly, then add the source-aligned pop pattern.","challenge":"First Pop Verse Performance","evidence":"Perform a complete verse using G-C-Em-D and a steady pop strumming pattern.","rubric":[{"name":"Chord accuracy","weight":20},{"name":"Transition continuity","weight":20},{"name":"Strumming accuracy","weight":20},{"name":"Memory and complete form","weight":25},{"name":"Reflection and preparation","weight":15}],"sort":7,"objective":"Develop and demonstrate source-aligned Guitar skills for Pop Song Power: Your First Verse.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":8,"title":"Rock Power: Intro to Power Chords","lessons":["Two-Finger Power-Chord Shape","G5, A5, and C5","Sliding the Shape Safely"],"practice":"Power-Chord Position Drill","practiceInstructions":"Form G5, A5, and C5, mute unused strings, and slide between two positions.","challenge":"Power-Chord Slide Performance","evidence":"Submit G5, A5, and C5 plus at least two controlled slides in a short rock phrase.","rubric":[{"name":"Power-chord shape","weight":25},{"name":"Muting and clarity","weight":20},{"name":"Slide control","weight":20},{"name":"Rhythm and continuity","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":8,"objective":"Develop and demonstrate source-aligned Guitar skills for Rock Power: Intro to Power Chords.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":9,"title":"Ear Buddy: Playing by Listening","lessons":["Higher and Lower Pitch","Matching a Note","Finding a Three-Note Melody"],"practice":"Pitch-Matching Listening Drill","practiceInstructions":"Match short teacher-provided notes and identify melodic direction.","challenge":"Three-Note Melody by Ear","evidence":"Reproduce a simple three-note melody without written notation and describe the listening process.","rubric":[{"name":"Pitch matching","weight":25},{"name":"Melodic accuracy","weight":25},{"name":"Listening process","weight":20},{"name":"Performance control","weight":15},{"name":"Reflection and completeness","weight":15}],"sort":9,"objective":"Develop and demonstrate source-aligned Guitar skills for Ear Buddy: Playing by Listening.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":10,"title":"Creativity Sprint: Write a Rock Riff","lessons":["Building a Note Bank","Rhythm Shapes for Riffs","Repetition and Memorability"],"practice":"Four-Note Riff Sketch","practiceInstructions":"Combine four to six approved notes into an eight-beat repeating idea.","challenge":"Original Beginner Rock Riff","evidence":"Submit a repeatable original riff of at least eight beats and explain one creative choice.","rubric":[{"name":"Note-bank use","weight":20},{"name":"Rhythmic clarity","weight":25},{"name":"Repeatability","weight":20},{"name":"Creativity and musical identity","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":10,"objective":"Develop and demonstrate source-aligned Guitar skills for Creativity Sprint: Write a Rock Riff.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":11,"title":"Capstone Rehearsal & Polish","lessons":["Selecting a Showcase Piece","Isolating Problem Spots","Full-Run Performance Practice"],"practice":"Problem-Spot Rehearsal Log","practiceInstructions":"Identify two difficult passages, practice each slowly, and record improvement notes.","challenge":"Beginner Showcase Rehearsal","evidence":"Submit a complete rehearsal take and a short polish plan for the final capstone.","rubric":[{"name":"Preparation strategy","weight":20},{"name":"Technical improvement","weight":20},{"name":"Full-run continuity","weight":25},{"name":"Musical presentation","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":11,"objective":"Develop and demonstrate source-aligned Guitar skills for Capstone Rehearsal & Polish.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":1,"num":12,"title":"Showtime! Beginner Capstone","lessons":["Final Performance Preparation","Recording a Complete Take","Reflecting on Beginner Growth"],"practice":"Showcase Sound and Camera Check","practiceInstructions":"Test framing, audio clarity, tuning, and a complete warm-up run.","challenge":"Beginner Guitar Showcase","evidence":"Submit a complete performance of the rehearsed piece plus a reflection on growth and next goals.","rubric":[{"name":"Technique and accuracy","weight":25},{"name":"Rhythm and continuity","weight":20},{"name":"Musical expression","weight":20},{"name":"Performance preparation","weight":20},{"name":"Reflection and submission completeness","weight":15}],"sort":12,"objective":"Develop and demonstrate source-aligned Guitar skills for Showtime! Beginner Capstone.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":1,"title":"Power Chords & Rock Foundations","lessons":["Root Notes and Power-Chord Construction","Rock Rhythm Patterns","Building a Short Rock Form"],"practice":"Power-Chord Rhythm Circuit","practiceInstructions":"Cycle three power chords through two rock rhythm patterns.","challenge":"Rock Foundations Performance","evidence":"Submit a structured rock excerpt using at least three power chords and a consistent rhythm.","rubric":[{"name":"Chord construction","weight":20},{"name":"Muting and clarity","weight":20},{"name":"Rock rhythm accuracy","weight":25},{"name":"Form and musical energy","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":13,"objective":"Develop and demonstrate source-aligned Guitar skills for Power Chords & Rock Foundations.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":2,"title":"12-Bar Blues Pattern","lessons":["I-IV-V in E","Swing Strumming","Completing and Varying the Form"],"practice":"Three-Cycle Blues Groove","practiceInstructions":"Play three 12-bar cycles while maintaining the approved swing feel.","challenge":"Intermediate 12-Bar Blues","evidence":"Submit a complete blues performance in E with clear I-IV-V movement and swing rhythm.","rubric":[{"name":"Form accuracy","weight":25},{"name":"Chord relationship knowledge","weight":20},{"name":"Swing feel","weight":25},{"name":"Performance continuity","weight":15},{"name":"Reflection and completeness","weight":15}],"sort":14,"objective":"Develop and demonstrate source-aligned Guitar skills for 12-Bar Blues Pattern.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":3,"title":"Hammer-ons and Pull-offs","lessons":["Hammer-on Mechanics","Pull-off Mechanics","Combining Legato in a Riff"],"practice":"Legato Control Drill","practiceInstructions":"Practice repeated hammer-ons and pull-offs slowly with balanced volume.","challenge":"Sixteen-Bar Legato Riff","evidence":"Compose and perform a 16-bar riff containing at least five hammer-ons and three pull-offs.","rubric":[{"name":"Hammer-on clarity","weight":20},{"name":"Pull-off clarity","weight":20},{"name":"Timing and continuity","weight":20},{"name":"Musical integration","weight":25},{"name":"Reflection and completeness","weight":15}],"sort":15,"objective":"Develop and demonstrate source-aligned Guitar skills for Hammer-ons and Pull-offs.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":4,"title":"String Bending Techniques","lessons":["Supported Bending Mechanics","Half-Step and Whole-Step Targets","Expressive Bend Release"],"practice":"Pitch-Target Bend Drill","practiceInstructions":"Match half-step and whole-step bend targets at a safe tempo.","challenge":"Expressive Bending Performance","evidence":"Submit a phrase containing at least three controlled bends, including half-step and whole-step targets.","rubric":[{"name":"Pitch accuracy","weight":25},{"name":"Bend mechanics","weight":20},{"name":"Release control","weight":20},{"name":"Expression and phrasing","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":16,"objective":"Develop and demonstrate source-aligned Guitar skills for String Bending Techniques.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":5,"title":"Intro to Soloing: The Pentatonic Scale","lessons":["A Minor Pentatonic Shape","Scale-to-Chord Connection","First Improvised Phrases"],"practice":"Pentatonic Phrase Builder","practiceInstructions":"Play the first-position scale and create three short call-and-response phrases.","challenge":"A Minor Pentatonic Solo","evidence":"Submit a one- to two-minute solo using recognizable pentatonic phrases over an approved backing pulse.","rubric":[{"name":"Scale accuracy","weight":20},{"name":"Timing","weight":20},{"name":"Phrase construction","weight":25},{"name":"Expression and development","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":17,"objective":"Develop and demonstrate source-aligned Guitar skills for Intro to Soloing: The Pentatonic Scale.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":6,"title":"Rock Expression: String Bending & Vibrato","lessons":["Accurate Half- and Whole-Step Bends","Controlled Vibrato","Combining Bend and Vibrato"],"practice":"Sustain and Vibrato Study","practiceInstructions":"Sustain target notes, add even vibrato, and compare bend-to-vibrato transitions.","challenge":"Expressive Rock Lick","evidence":"Perform an original lick combining an accurate bend and controlled vibrato.","rubric":[{"name":"Bend accuracy","weight":20},{"name":"Vibrato control","weight":20},{"name":"Technique integration","weight":25},{"name":"Tone and expression","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":18,"objective":"Develop and demonstrate source-aligned Guitar skills for Rock Expression: String Bending & Vibrato.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":7,"title":"Reading Guitar Tablature (Tabs)","lessons":["Strings, Numbers, and Rhythm","Common Tab Symbols","Performing a Tab Melody"],"practice":"Eight-Measure Tab Reading","practiceInstructions":"Decode and rehearse a short tab containing at least one hammer-on and pull-off.","challenge":"Tab-to-Performance Challenge","evidence":"Submit an accurate performance from provided tablature and explain three symbols used.","rubric":[{"name":"Tab decoding","weight":25},{"name":"Note accuracy","weight":20},{"name":"Rhythm accuracy","weight":20},{"name":"Technique-symbol execution","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":19,"objective":"Develop and demonstrate source-aligned Guitar skills for Reading Guitar Tablature (Tabs).","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":8,"title":"Classic Blues Licks & Turnarounds","lessons":["Three Classic Blues Licks","Standard Turnaround","Placing Licks in 12-Bar Form"],"practice":"Blues Lick Call-and-Response","practiceInstructions":"Rehearse three licks and one turnaround over a slow blues pulse.","challenge":"Blues Licks and Turnaround Performance","evidence":"Perform three licks and a turnaround within a complete 12-bar context.","rubric":[{"name":"Lick accuracy","weight":20},{"name":"Turnaround accuracy","weight":20},{"name":"Placement in form","weight":25},{"name":"Blues phrasing","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":20,"objective":"Develop and demonstrate source-aligned Guitar skills for Classic Blues Licks & Turnarounds.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":2,"num":9,"title":"Writing Your First Rock Riff","lessons":["Anatomy of a Rock Riff","Combining Pentatonic Notes and Power Chords","Revision for Memorability"],"practice":"Riff Motif Workshop","practiceInstructions":"Develop a short motif using three power chords and selected pentatonic notes.","challenge":"Original Intermediate Rock Riff","evidence":"Submit a complete original riff combining single notes and power chords, plus a creative-process reflection.","rubric":[{"name":"Technique integration","weight":20},{"name":"Rhythm and continuity","weight":25},{"name":"Motif development","weight":20},{"name":"Originality","weight":20},{"name":"Reflection and 