1ths).","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":5,"title":"Practical Music Theory for Guitarists","lessons":["Intervals on the Fretboard","Harmonizing a Key","Applying Theory to Chords and Solos"],"practice":"Fretboard Theory Map","practiceInstructions":"Label scale degrees and build diatonic chords in one approved key.","challenge":"Applied Guitar Theory Demonstration","evidence":"Explain and perform a progression and short melody derived from one key.","rubric":[{"name":"Theory accuracy","weight":25},{"name":"Fretboard application","weight":20},{"name":"Chord-scale connection","weight":20},{"name":"Musical demonstration","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":31,"objective":"Develop and demonstrate source-aligned Guitar skills for Practical Music Theory for Guitarists.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":6,"title":"Improvisation Strategies","lessons":["Motifs and Development","Target Notes and Chord Changes","Building a Solo Arc"],"practice":"Motif Development Lab","practiceInstructions":"Transform one short motif through rhythm, register, and ending-note changes.","challenge":"Structured Improvised Solo","evidence":"Submit a solo with a recognizable motif, chord awareness, contrast, and a clear ending.","rubric":[{"name":"Chord-aware note choice","weight":20},{"name":"Motif development","weight":25},{"name":"Rhythm and phrasing","weight":20},{"name":"Solo structure and expression","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":32,"objective":"Develop and demonstrate source-aligned Guitar skills for Improvisation Strategies.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":7,"title":"Composing a Guitar Solo","lessons":["Mapping Chord Changes","Developing Themes","Revising and Notating a Solo"],"practice":"Eigh