e":"Subdivision accuracy","weight":25},{"name":"Muting technique","weight":20},{"name":"Syncopation and pocket","weight":20},{"name":"Dynamics and style","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":35,"objective":"Develop and demonstrate source-aligned Guitar skills for Advanced Rhythm Guitar: Funk & R&B.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":10,"title":"Using Effects Pedals","lessons":["Signal Chain and Effect Families","Gain, Modulation, and Time Effects","Choosing Effects for a Musical Purpose"],"practice":"Effect A/B Listening Study","practiceInstructions":"Compare dry tone with two effect settings and document the musical impact.","challenge":"Purposeful Guitar Effects Performance","evidence":"Submit one phrase in multiple effect treatments and justify the final signal choice.","rubric":[{"name":"Signal-chain understanding","weight":20},{"name":"Controlled settings","weight":20},{"name":"Tone clarity","weight":20},{"name":"Musical appropriateness","weight":25},{"name":"Reflection and completeness","weight":15}],"sort":36,"objective":"Develop and demonstrate source-aligned Guitar skills for Using Effects Pedals.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":11,"title":"Ear Training for Guitarists","lessons":["Recognizing Intervals","Identifying Chord Qualities","Transcribing a Short Melody"],"practice":"Interval and Melody Dictation","practiceInstructions":"Identify selected intervals and locate a short phrase on the guitar.","challenge":"Guitar Ear-Training Demonstration","evidence":"Reproduce and explain a teacher-provided melodic or harmonic excerpt by ear.","rubric":[{"name":"Interval recognition","weight":20},{"name":"Pitch and chord identification","weight":20},{"name":"Transcription accuracy","weight":25},{"name":"Guitar realization","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":37,"objective":"Develop and demonstrate source-aligned Guitar skills for Ear Training for Guitarists.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":3,"num":12,"title":"Level Capstone: Write & Record an Original","lessons":["Original-Song Planning","Guitar Arrangement and Rehearsal","Recording and Artistic Reflection"],"practice":"Original Work Production Check","practiceInstructions":"Submit a structure map, rehearsal excerpt, and revision priorities.","challenge":"Advanced Original Guitar Recording","evidence":"Write, arrange, perform, and record an original work with a documented creative process.","rubric":[{"name":"Composition and structure","weight":25},{"name":"Guitar technique and arrangement","weight":20},{"name":"Rhythm and recording execution","weight":20},{"name":"Artistic expression","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":38,"objective":"Develop and demonstrate source-aligned Guitar skills for Level Capstone: Write & Record an Original.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":1,"title":"Harmonic Minor Scale Applications","lessons":["Harmonic Minor Construction","Dominant Resolution and Characteristic Notes","Applying the Scale to a Solo"],"practice":"Harmonic Minor Resolution Drill","practiceInstructions":"Practice characteristic scale tones and resolve phrases to stable targets.","challenge":"Harmonic Minor Application Solo","evidence":"Submit a musical solo demonstrating accurate harmonic-minor use and intentional resolution.","rubric":[{"name":"Scale accuracy","weight":25},{"name":"Harmonic application","weight":20},{"name":"Resolution and phrasing","weight":20},{"name":"Technique and expression","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":39,"objective":"Develop and demonstrate source-aligned Guitar skills for Harmonic Minor Scale Applications.","concern":"AI-