 Guitar","lessons":["Neo-Soul Voicings","Slides, Embellishments, and Inner Voices","Modern R&B Groove Arrangement"],"practice":"Neo-Soul Embellishment Loop","practiceInstructions":"Connect two advanced voicings with slides, hammer-ons, or inner-voice movement.","challenge":"Neo-Soul/R&B Guitar Arrangement","evidence":"Submit a polished progression featuring advanced voicings, embellishments, pocket, and dynamic nuance.","rubric":[{"name":"Voicing accuracy","weight":20},{"name":"Embellishment control","weight":20},{"name":"Groove and pocket","weight":25},{"name":"Arrangement and expression","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":42,"objective":"Develop and demonstrate source-aligned Guitar skills for Neo-Soul & Modern R&B Guitar.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":5,"title":"The Circle of Fifths","lessons":["Reading the Circle","Key Signatures and Related Keys","Applying the Circle to Guitar Composition"],"practice":"Circle-Based Progression Map","practiceInstructions":"Build and play progressions in two related keys using the circle.","challenge":"Circle of Fifths Composition Study","evidence":"Submit a progression or short composition demonstrating modulation or related-key planning and explain the map.","rubric":[{"name":"Circle knowledge","weight":25},{"name":"Key relationship accuracy","weight":20},{"name":"Guitar application","weight":20},{"name":"Creative harmonic use","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":43,"objective":"Develop and demonstrate source-aligned Guitar skills for The Circle of Fifths.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":6,"title":"Transcription & Analysis","lessons":["Segmenting a Recording","Transcribing Rhythm and Pitch","Analyzing Style and Harmony"],"practice":"Four-Bar Transcription Pass","practiceInstructions":"Transcribe a short approved excerpt and document verification steps.","challenge":"Guitar Transcription and Analysis","evidence":"Submit an accurate transcription, performance, and analysis of a teacher-approved excerpt.","rubric":[{"name":"Pitch and rhythm accuracy","weight":25},{"name":"Guitar realization","weight":20},{"name":"Harmonic/style analysis","weight":20},{"name":"Documentation process","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":44,"objective":"Develop and demonstrate source-aligned Guitar skills for Transcription & Analysis.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":7,"title":"Developing Your Artistic Voice","lessons":["Identifying Influences","Defining Signature Choices","Creating an Artist Statement through Guitar"],"practice":"Influence-to-Identity Study","practiceInstructions":"Compare two influences and create a phrase that transforms rather than copies their traits.","challenge":"Artistic Voice Performance Statement","evidence":"Submit an original performance and reflection identifying intentional tone, phrasing, repertoire, and presentation choices.","rubric":[{"name":"Technical command","weight":20},{"name":"Original artistic choices","weight":25},{"name":"Coherence of style","weight":20},{"name":"Performance communication","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":45,"objective":"Develop and demonstrate source-aligned Guitar skills for Developing Your Artistic Voice.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":8,"title":"Studio Recording Techniques","lessons":["Guitar Signal and Microphone Choices","Capturing Clean Takes","Layering, Editing, and Mix Preparation"],"practice":"Two-Capture Method Comparison","practiceInstructions":"Record the same guitar phrase using two approved capture approaches and compare results.","challenge":"Studio-Ready Guitar Recording","evidence":"Submit a polished guitar recording with documented signal path, take selection, and basic mix decisions.","rubric":[{"name":"Recording setup","weight":20},{"name":"Performance accuracy","weight":20},{"name":"Audio clarity","weight":25},{"name":"Production decisions","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":46,"objective":"Develop and demonstrate source-aligned Guitar skills for Studio Recording Techniques.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":9,"title":"Live Performance Strategies","lessons":["Set Planning and Transitions","Soundcheck and Stage Communication","Performance Recovery and Audience Connection"],"practice":"Live Set Run-of-Show","practiceInstructions":"Prepare a short set list, soundcheck checklist, and transition rehearsal.","challenge":"Master Live Performance Simulation","evidence":"Submit a continuous performance set demonstrating preparation, transitions, stage communication, and recovery.","rubric":[{"name":"Performance preparation","weight":20},{"name":"Technical consistency","weight":20},{"name":"Transitions and continuity","weight":20},{"name":"Communication and presence","weight":25},{"name":"Reflection and completeness","weight":15}],"sort":47,"objective":"Develop and demonstrate source-aligned Guitar skills for Live Performance Strategies.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":10,"title":"Capstone: Write and Record an Original","lessons":["Master-Level Composition Plan","Performance and Production Execution","Revision and Release-Readiness Review"],"practice":"Original Work Preflight","practiceInstructions":"Submit form, harmony, guitar-part, recording, and revision plans before the complete take.","challenge":"Master Original Guitar Work","evidence":"Compose, perform, and record an original piece demonstrating advanced technique, musical identity, and production judgment.","rubric":[{"name":"Composition and structure","weight":25},{"name":"Advanced guitar execution","weight":20},{"name":"Recording and production","weight":20},{"name":"Artistic identity","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":48,"objective":"Develop and demonstrate source-aligned Guitar skills for Capstone: Write and Record an Original.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":11,"title":"Arranging for Guitar","lessons":["Assigning Guitar Roles","Register, Texture, and Voice Leading","Building a Complete Arrangement"],"practice":"Three-Layer Guitar Arrangement Sketch","practiceInstructions":"Draft rhythm, lead, and texture roles without frequency or register conflict.","challenge":"Complete Guitar Arrangement","evidence":"Submit an arrangement demonstrating purposeful roles, dynamics, space, and a coherent musical arc.","rubric":[{"name":"Role and texture planning","weight":25},{"name":"Harmonic/voice-leading accuracy","weight":20},{"name":"Performance execution","weight":20},{"name":"Arrangement effectiveness","weight":20},{"name":"Reflection and completeness","weight":15}],"sort":49,"objective":"Develop and demonstrate source-aligned Guitar skills for Arranging for Guitar.","concern":"AI-PROPOSED completion criteria require Guitar teacher and leadership review."},{"level":4,"num":12,"title":"Final Capstone: Produce a 3-Song EP","lessons":["EP Concept and Song Selection","Production Consistency across Three Songs","Final Presentation and Master Reflection"],"practice":"EP Production Readiness Review","practiceInstructions":"Present the three-song plan, production schedule, quality checklist, and revision priorities.","challenge":"Three-Song Guitar EP Capstone","evidence":"Submit a coherent three-song EP or teacher-approved equivalent demonstrating composition/arrangement, guitar performance, recording, and artistic identity.","rubric":[{"name":"Song and project coherence","weight":20},{"name":"Guitar performance quality","weight":25},{"name":"Arrangement and production quality","weight":20},{"name":"Artistic identity and presentation","weight":20},{"name":"Reflection and submission completeness","weight":15}],"sort":50,"objective":"Develop and demonstrate source-aligned Guitar skills for Final Capstone: Produce a 3-Song EP.","concern":"PROGRAM PDF END POINT; Tutor-only Master modules 13-15 are excluded."}]'::jsonb)
 as x(level int,num int,sort int,title text,lessons jsonb,practice text,"practiceInstructions" text,challenge text,evidence text,rubric jsonb,objective text,concern text) order by sort loop
  v_level_title:=(array['Beginner','Intermediate','Advanced','Master'])[r.level];
  v_level_target:=case when r.level=2 then 8750 else 7500 end;
  select id into v_level from public.course_levels where course_id=v_course and level_number=r.level;
  if v_level is null then
   insert into public.course_levels(id,course_id,level_number,title,description,learning_objectives,status,core_xp_target,review_notes)
   values(gen_random_uuid(),v_course,r.level,v_level_title,v_level_title||' Guitar curriculum. Draft review only.',array['Complete the source-aligned Guitar level curriculum.'],'draft',v_level_target,'Guitar full draft rollout 202608140001; batch-created level; metadata target reconciliation deferred.') returning id into v_level;
  elsif not exists(select 1 from public.course_levels where id=v_level and course_id=v_course and level_number=r.level and title=v_level_title and status='draft' and approved_by is null and approved_at is null)
  then raise exception 'Incompatible existing Guitar Level %',r.level; end if;
  select id into v_module from public.course_modules where course_level_id=v_level and level_module_number=r.num;
  v_review_notes:='Guitar full draft rollout 202608140001; AI-PROPOSED; NEEDS TEACHER REVIEW; Media NEEDS REVIEW; Tools NEEDS CATALOG REVIEW; Career Path NOT CONFIGURED. '||r.concern;
  if v_module is null then
   if exists(select 1 from public.course_modules where course_id=v_course and (sort_order=r.sort or title=r.title)) then raise exception 'Guitar module identity conflict Level %, Module %',r.level,r.num; end if;
   insert into public.course_modules(id,course_id,course_level_id,level_module_number,title,description,short_intro,sort_order,xp_value,core_xp,intro_core_xp,video_core_xp,assignment_core_xp,mastery_core_xp,core_unlock_threshold,bonus_xp_available,jpac_tool_activity,real_world_activity,career_connection,portfolio_moment,status,video_brief,aria_coaching_targets,career_mission_ideas,review_notes)
   values(gen_random_uuid(),v_course,v_level,r.num,r.title,r.objective,r.objective,r.sort,625,625,50,100,350,125,438,0,jsonb_build_object('review_status','NEEDS CATALOG REVIEW'),jsonb_build_object('title',r.practice,'instructions',r."practiceInstructions"),'',false,'draft','NEEDS REVIEW: no media is activated.',jsonb_build_object('advisory_only',true,'targets',jsonb_build_array(r.title,'guitar terminology','practice coaching','confidence-building feedback'),'prohibited',jsonb_build_array('assess','approve','award XP','grant mastery','unlock')),'[]'::jsonb,v_review_notes) returning id into v_module;
  elsif not exists(select 1 from public.course_modules where id=v_module and course_id=v_course and course_level_id=v_level and level_module_number=r.num and title=r.title and description=r.objective and short_intro=r.objective and sort_order=r.sort and xp_value=625 and core_xp=625 and intro_core_xp=50 and video_core_xp=100 and assignment_core_xp=350 and mastery_core_xp=125 and core_unlock_threshold=438 and bonus_xp_available=0 and status='draft' and jpac_tool_activity=jsonb_build_object('review_status','NEEDS CATALOG REVIEW') and real_world_activity=jsonb_build_object('title',r.practice,'instructions',r."practiceInstructions") and career_connection='' and not portfolio_moment and video_brief='NEEDS REVIEW: no media is activated.' and lab_tool_id is null and active_instructional_media_id is null and primary_video_url is null and approved_by is null and approved_at is null)
  then raise exception 'Incompatible existing Guitar module Level %, Module %',r.level,r.num; end if;
  v_rubric:=jsonb_build_object('criteria',(select jsonb_agg(jsonb_build_object('name',item->>'name','weight',(item->>'weight')::int,'bands',jsonb_build_object('Exceeds','Consistently exceeds the approved standard.','Meets','Meets the approved standard.','Developing','Partially meets the standard.','Not Yet','Does not yet meet the standard.')) order by ord) from jsonb_array_elements(r.rubric) with ordinality q(item,ord)));
  if exists(select 1 from public.lessons where module_id=v_module) or exists(select 1 from public.activities where module_id=v_module) then
   if (select count(*) from public.lessons where module_id=v_module)<>3 or (select count(*) from public.activities where module_id=v_module)<>2
   or exists(select 1 from jsonb_array_elements_text(r.lessons) with ordinality expected(title,ord) left join public.lessons l on l.module_id=v_module and l.sort_order=ord where l.id is null or l.title is distinct from expected.title or l.learning_objective is distinct from 'Study and apply '||expected.title||' within '||r.title||'.' or l.status is distinct from 'draft' or l.xp_value is distinct from 0)
   or not exists(select 1 from public.activities where module_id=v_module and lesson_id is null and title=r.practice and description='Optional source-aligned Guitar preparation.' and activity_type='practice' and instructions=r."practiceInstructions" and submission_type='none' and xp_reward=0 and xp_type='bonus' and not required and status='draft' and passing_score=70 and allows_resubmission and not portfolio_candidate and not coalesce(certificate_eligible,false))
   or not exists(select 1 from public.activities where module_id=v_module and lesson_id is null and title=r.challenge and description='Required source-aligned Guitar Core Challenge.' and activity_type='performance' and instructions=r.evidence||' Use the existing JPAC submission and teacher-review workflow.' and submission_type='video' and xp_reward=350 and xp_type='core' and required and status='draft' and passing_score=70 and allows_resubmission and rubric=v_rubric and not portfolio_candidate and not coalesce(certificate_eligible,false))
   then raise exception 'Existing Guitar child payload conflict Level %, Module %',r.level,r.num; end if;
  else
   for i in 0..2 loop v_lesson:=r.lessons->i;
    insert into public.lessons(id,module_id,title,description,lesson_type,duration_minutes,sort_order,xp_value,status,short_summary,learning_objective,content_blocks,technique_cues,common_mistakes,self_check,resource_brief)
    values(gen_random_uuid(),v_module,v_lesson#>>'{}','Study and apply '||(v_lesson#>>'{}')||' within '||r.title||'.','interactive',25,i+1,0,'draft','Source-aligned Guitar lesson; draft review only.','Study and apply '||(v_lesson#>>'{}')||' within '||r.title||'.',jsonb_build_array('Review the source-aligned concept.','Practice slowly with a teacher-approved adaptation.','Reflect on one strength and one next step.'),array['Control before speed','Release unnecessary tension','ARIA is advisory only'],array['Rushing','Ignoring tension','Skipping reflection'],'Can you demonstrate the objective and name one next step?','AI-PROPOSED accessibility/no-tool alternatives require Guitar teacher review.');
   end loop;
   insert into public.activities(id,course_id,module_id,title,description,activity_type,instructions,submission_type,xp_reward,estimated_minutes,required,status,rubric,skill_tags,ai_summary,xp_type,passing_score,allows_resubmission,portfolio_candidate,certificate_eligible) values
   (gen_random_uuid(),v_course,v_module,r.practice,'Optional source-aligned Guitar preparation.','practice',r."practiceInstructions",'none',0,20,false,'draft','{}'::jsonb,'{}'::text[],'AI-PROPOSED; optional, non-progressive, non-assessed; teacher review required.','bonus',70,true,false,false),
   (gen_random_uuid(),v_course,v_module,r.challenge,'Required source-aligned Guitar Core Challenge.','performance',r.evidence||' Use the existing JPAC submission and teacher-review workflow.','video',350,30,true,'draft',v_rubric,'{}'::text[],'AI-PROPOSED; teacher review required; ARIA advisory only.','core',70,true,false,false);
  end if;
 end loop;
end $$;
commit;
